import { useState, useEffect, useContext } from "react";
import api from "../api";
import { AuthContext } from "../contexts/AuthContext";
import { useNavigate } from "react-router-dom";
import Modal from "../components/Modal";

export default function AdminDashboard() {
  const [votingOpen, setVotingOpen] = useState(false);
  const [pendingUsers, setPendingUsers] = useState([]);
  const [candidates, setCandidates] = useState([]);
  const [logs, setLogs] = useState([]);
  const [reportHash, setReportHash] = useState("");

  const [candidateModalOpen, setCandidateModalOpen] = useState(false);
  const [editingCandidate, setEditingCandidate] = useState(null);
  const [candidateForm, setCandidateForm] = useState({ name: "", position: "", party: "" });

  const { logout } = useContext(AuthContext);
  const navigate = useNavigate();

  useEffect(() => {
    fetchVotingState();
    fetchPendingUsers();
    fetchCandidates();
    fetchLogs();
  }, []);

  // ---------------- Backend Calls ----------------
  const fetchVotingState = async () => {
    try {
      const res = await api.get("/admin/voting-state");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.error("Voting state fetch failed:", err);
      alert(`Error fetching voting state: ${err.response?.data?.error || err.message}`);
    }
  };

  const fetchPendingUsers = async () => {
    try {
      const res = await api.get("/admin/pending-users");
      setPendingUsers(res.data);
    } catch (err) {
      console.error("Pending users fetch failed:", err);
      alert(`Error fetching pending users: ${err.response?.data?.error || err.message}`);
    }
  };

  const fetchCandidates = async () => {
    try {
      const res = await api.get("/admin/candidates");
      setCandidates(res.data);
    } catch (err) {
      console.error("Candidates fetch failed:", err);
      alert(`Error fetching candidates: ${err.response?.data?.error || err.message}`);
    }
  };

  const fetchLogs = async () => {
    try {
      const res = await api.get("/admin/logs");
      setLogs(res.data);
    } catch (err) {
      console.error("Logs fetch failed:", err);
      alert(`Error fetching logs: ${err.response?.data?.error || err.message}`);
    }
  };

  const toggleVoting = async () => {
    try {
      const res = await api.post("/admin/toggle-voting");
      setVotingOpen(res.data.votingOpen);
    } catch (err) {
      console.error("Toggle voting failed:", err);
      alert(`Error toggling voting: ${err.response?.data?.error || err.message}`);
    }
  };

  const approveUser = async (id) => {
    try {
      await api.post(`/admin/approve-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      console.error("Approve user failed:", err);
      alert(`Error approving user: ${err.response?.data?.error || err.message}`);
    }
  };

  const rejectUser = async (id) => {
    try {
      await api.post(`/admin/reject-user/${id}`);
      fetchPendingUsers();
    } catch (err) {
      console.error("Reject user failed:", err);
      alert(`Error rejecting user: ${err.response?.data?.error || err.message}`);
    }
  };

  const generateReport = async () => {
    try {
      const res = await api.post("/admin/generate-report");
      setReportHash(res.data.hash);
    } catch (err) {
      console.error("Generate report failed:", err);
      alert(`Error generating report: ${err.response?.data?.error || err.message}`);
    }
  };

  // ---------------- Candidate CRUD ----------------
  const openCandidateModal = (candidate = null) => {
    setEditingCandidate(candidate);
    setCandidateForm(candidate ? { name: candidate.name, position: candidate.position, party: candidate.party || "" } : { name: "", position: "", party: "" });
    setCandidateModalOpen(true);
  };

  const closeCandidateModal = () => {
    setCandidateModalOpen(false);
    setEditingCandidate(null);
  };

  const handleCandidateFormChange = (e) => {
    setCandidateForm({ ...candidateForm, [e.target.name]: e.target.value });
  };

  const saveCandidate = async () => {
    const { name, position, party } = candidateForm;
    if (!name || !position) return alert("Name and Position are required");
    try {
      if (editingCandidate) {
        await api.put(`/admin/candidates/${editingCandidate.id}`, { name, position, party });
      } else {
        await api.post(`/admin/candidates`, { name, position, party });
      }
      fetchCandidates();
      closeCandidateModal();
    } catch (err) {
      console.error("Save candidate failed:", err);
      alert(`Error saving candidate: ${err.response?.data?.error || err.message}`);
    }
  };

  const deleteCandidate = async (id) => {
    if (!window.confirm("Delete this candidate?")) return;
    try {
      await api.delete(`/admin/candidates/${id}`);
      fetchCandidates();
    } catch (err) {
      console.error("Delete candidate failed:", err);
      alert(`Error deleting candidate: ${err.response?.data?.error || err.message}`);
    }
  };

  // ---------------- JSX ----------------
  return (
    <div className="min-h-screen bg-gray-100">
      {/* Header */}
      <header className="bg-white shadow-md py-4 px-6 flex justify-between items-center">
        <h1 className="text-2xl font-bold">iVote Admin Dashboard</h1>
        <button
          onClick={() => { logout(); navigate("/login"); }}
          className="bg-red-600 text-white px-4 py-2 rounded hover:bg-red-700"
        >
          Logout
        </button>
      </header>

      <main className="p-6 space-y-6">
        {/* Voting Status */}
        <section className="bg-white p-6 rounded-xl shadow-md flex justify-between items-center">
          <div>
            <h2 className="text-xl font-semibold">Voting Status</h2>
            <p className={votingOpen ? "text-green-600" : "text-red-600"}>{votingOpen ? "Open" : "Closed"}</p>
          </div>
          <button
            onClick={toggleVoting}
            className={`px-6 py-3 rounded-lg font-semibold text-white ${votingOpen ? "bg-red-600 hover:bg-red-700" : "bg-green-600 hover:bg-green-700"}`}
          >
            {votingOpen ? "Close Voting" : "Open Voting"}
          </button>
        </section>

        {/* Pending Users */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-xl font-semibold mb-4">Pending Voter Registrations</h2>
          {pendingUsers.length === 0 ? (
            <p className="text-gray-500">No pending users.</p>
          ) : (
            <table className="w-full table-auto border-collapse border border-gray-200">
              <thead>
                <tr className="bg-gray-100">
                  <th className="border px-4 py-2">Student Number</th>
                  <th className="border px-4 py-2">Name</th>
                  <th className="border px-4 py-2">Email</th>
                  <th className="border px-4 py-2">Actions</th>
                </tr>
              </thead>
              <tbody>
                {pendingUsers.map((user) => (
                  <tr key={user.id}>
                    <td className="border px-4 py-2">{user.studentNumber}</td>
                    <td className="border px-4 py-2">{user.name}</td>
                    <td className="border px-4 py-2">{user.email}</td>
                    <td className="border px-4 py-2 space-x-2">
                      <button onClick={() => approveUser(user.id)} className="bg-green-600 text-white px-3 py-1 rounded hover:bg-green-700">Approve</button>
                      <button onClick={() => rejectUser(user.id)} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700">Reject</button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </section>

        {/* Candidates */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <div className="flex justify-between items-center mb-4">
            <h2 className="text-xl font-semibold">Candidates</h2>
            <button onClick={() => openCandidateModal()} className="bg-blue-600 text-white px-4 py-2 rounded hover:bg-blue-700">Add Candidate</button>
          </div>

          <table className="w-full table-auto border-collapse border border-gray-200">
            <thead>
              <tr className="bg-gray-100">
                <th className="border px-4 py-2">Name</th>
                <th className="border px-4 py-2">Position</th>
                <th className="border px-4 py-2">Party</th>
                <th className="border px-4 py-2">Actions</th>
              </tr>
            </thead>
            <tbody>
              {candidates.map((c) => (
                <tr key={c.id} className="hover:bg-gray-50">
                  <td className="border px-4 py-2">{c.name}</td>
                  <td className="border px-4 py-2">{c.position}</td>
                  <td className="border px-4 py-2">{c.party || "-"}</td>
                  <td className="border px-4 py-2 space-x-2">
                    <button onClick={() => openCandidateModal(c)} className="bg-blue-600 text-white px-3 py-1 rounded hover:bg-blue-700">Edit</button>
                    <button onClick={() => deleteCandidate(c.id)} className="bg-red-600 text-white px-3 py-1 rounded hover:bg-red-700">Delete</button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>

        {/* System Logs */}
        <section className="bg-white p-6 rounded-xl shadow-md">
          <h2 className="text-xl font-semibold mb-4">System Logs</h2>
          {logs.length === 0 ? (
            <p className="text-gray-500">No logs available.</p>
          ) : (
            <ul className="space-y-2 max-h-64 overflow-y-auto">
              {logs.map((log) => (
                <li key={log.id} className="text-gray-700">
                  {log.action} <span className="text-gray-400 text-sm">{new Date(log.createdAt).toLocaleString()}</span>
                </li>
              ))}
            </ul>
          )}
        </section>

        {/* Reports */}
        <section className="bg-white p-6 rounded-xl shadow-md flex flex-col items-start space-y-3">
          <h2 className="text-xl font-semibold text-gray-800">Reports</h2>
          <button onClick={generateReport} className="bg-green-600 text-white px-4 py-2 rounded hover:bg-green-700">Generate Final Report</button>
          {reportHash && <p className="text-gray-600 mt-2">Cryptographic Hash: <span className="font-mono">{reportHash}</span></p>}
        </section>
      </main>

      {/* Candidate Modal */}
      {candidateModalOpen && (
        <Modal
          title={editingCandidate ? "Edit Candidate" : "Add Candidate"}
          onClose={closeCandidateModal}
          actions={[{ label: editingCandidate ? "Save Changes" : "Add Candidate", onClick: saveCandidate, className: "bg-blue-600 text-white hover:bg-blue-700" }]}
        >
          <div className="space-y-3">
            <input type="text" name="name" placeholder="Name" value={candidateForm.name} onChange={handleCandidateFormChange} className="w-full border px-3 py-2 rounded" />
            <input type="text" name="position" placeholder="Position" value={candidateForm.position} onChange={handleCandidateFormChange} className="w-full border px-3 py-2 rounded" />
            <input type="text" name="party" placeholder="Party (optional)" value={candidateForm.party} onChange={handleCandidateFormChange} className="w-full border px-3 py-2 rounded" />
          </div>
        </Modal>
      )}
    </div>
  );
}
